-- BRSR Report 2025-26: publish the uploaded PDF on the Sustainability (ESG) Reports page.
-- The BRSR card shows "Explore" and opens this file from the same origin (/files/...),
-- so it works on private IP, public IP and the domain without any storage-host URL.
-- Safe to run more than once.

INSERT INTO public.ir_files (path, mime, size, data, updated_at)
VALUES ('reports/BRSR_2025-26.pdf', 'application/pdf', 2203756, '\', now())
ON CONFLICT (path) DO UPDATE
SET mime = EXCLUDED.mime,
    size = EXCLUDED.size,
    data = EXCLUDED.data,
    updated_at = now();

UPDATE public.esg_items
SET url = 'storage:reports/BRSR_2025-26.pdf',
    updated_at = now()
WHERE page_slug = 'esg-reporting'
  AND kind = 'report'
  AND title = 'BRSR Report';
